function load(){try{let x=window.initialCloud||JSON.parse(localStorage.getItem(window.appStoreKey||STORE)||"{}");if(Array.isArray(x.words)&&x.words.length)words=x.words;coins=x.coins||0;unlocked={...unlocked,...x.unlocked};stats={...stats,...x.stats}}catch(e){}}
function save(){let payload={words,coins,unlocked,stats};try{localStorage.setItem(window.appStoreKey||STORE,JSON.stringify(payload))}catch(e){};if(window.persistCloud)window.persistCloud(payload)}
function freshDeck(){deck=shuffle([...words]);pos=0;used.clear()}
function nextWord(){if(pos>=deck.length)freshDeck();let w=deck[pos++];used.add(w.ka+"|"+w.ru);return w}
function award(n){coins+=n;stats.correct++;save();renderWallet();renderCards();renderShop()}
function renderWallet(){$("coins").textContent=coins}
function renderCards(){$("modeCards").innerHTML="";modes.forEach(m=>{let open=!!unlocked[m.id],d=document.createElement("article");d.className="mode"+(open?"":" locked");d.innerHTML=`<div class="emoji">${m.emoji}</div><h3>${m.title}</h3><p>${m.desc}</p><div class="tag">${open?"🔓 გახსნილია":`🔒 ფასი: ${m.price} 🪙`}</div><button class="btn ${open?"":"gold"}">${open?"თამაშის დაწყება":"შეძენა"}</button>`;d.querySelector("button").onclick=()=>open?start(m.id):buy(m.id);$("modeCards").appendChild(d)});$("progress").textContent=`${words.length} სიტყვა • ${Math.ceil(words.length/100)} დონე (100-ეული)`}
function renderShop(){$("shop").innerHTML="";modes.filter(m=>m.price>0).forEach(m=>{let d=document.createElement("div");d.className="shoprow";let left=document.createElement("div");left.innerHTML=`<b>${m.emoji} ${m.title}</b><div class="small">${m.desc}</div>`;let b=document.createElement("button");b.className="btn "+(unlocked[m.id]?"secondary":"gold");b.textContent=unlocked[m.id]?"შეძენილია":`${m.price} 🪙`;b.disabled=!!unlocked[m.id]||coins<m.price;b.onclick=()=>buy(m.id);d.append(left,b);$("shop").appendChild(d)})}
function buy(id){let m=modes.find(x=>x.id===id);if(!m||unlocked[id]||coins<m.price)return;coins-=m.price;unlocked[id]=true;save();renderWallet();renderCards();renderShop();start(id)}
function start(id){if(!unlocked[id])return;mode=id;$("gamePanel").hidden=false;["quiz","match","builder","dialogue","memory","hunt"].forEach(x=>$(x).hidden=x!==id);let m=modes.find(x=>x.id===id);$("gameTitle").textContent=m.emoji+" "+m.title;$("gameDesc").textContent=m.desc;newRound();$("gamePanel").scrollIntoView({behavior:"smooth",block:"start"})}
function newRound(){if(mode==="quiz")quizNew();if(mode==="match")matchNew();if(mode==="builder")builderNew();if(mode==="dialogue")dialogueNew();if(mode==="memory")memoryNew();if(mode==="hunt")huntNew()}
function quizNew(){current=nextWord();answered=false;$("qWord").textContent=current.ka;$("qFeedback").textContent="";$("qFeedback").className="feedback";$("qNext").disabled=true;let distract=shuffle(words.filter(w=>w.ru!==current.ru)).slice(0,3).map(w=>w.ru);let opts=shuffle([current.ru,...distract]);$("qOptions").innerHTML="";opts.forEach(v=>{let b=document.createElement("button");b.className="option";b.textContent=v;b.onclick=()=>{if(answered)return;answered=true;[...$("qOptions").children].forEach(x=>{x.disabled=true;if(x.textContent===current.ru)x.classList.add("correct")});if(v===current.ru){$("qFeedback").textContent="+10 🪙 სწორია!";$("qFeedback").className="feedback good";award(10)}else{b.classList.add("wrong");$("qFeedback").textContent="სწორი პასუხია: "+current.ru;$("qFeedback").className="feedback bad"}$("qNext").disabled=false};$("qOptions").appendChild(b)})}
function matchNew(){round=Array.from({length:Math.min(10,words.length)},()=>nextWord());matched=new Set();selected=null;$("mFeedback").textContent="";$("kaTiles").innerHTML="";$("ruTiles").innerHTML="";let ru=shuffle(round);round.forEach((w,i)=>tile($("kaTiles"),w.ka,i,()=>{if(matched.has(i))return;selected=i;document.querySelectorAll("#kaTiles .tile").forEach(x=>x.classList.remove("selected"));$("kaTiles").children[i].classList.add("selected")}));ru.forEach(w=>{let i=round.indexOf(w);tile($("ruTiles"),w.ru,i,()=>{if(matched.has(i))return;if(selected===null){$("mFeedback").textContent="ჯერ ქართული აირჩიე";return}if(selected===i){matched.add(i);$("kaTiles").children[i].classList.add("done");[...$("ruTiles").children].find(x=>+x.dataset.i===i).classList.add("done");$("mFeedback").textContent="+5 🪙 წყვილი სწორია";$("mFeedback").className="feedback good";award(5);if(matched.size===round.length)$("mFeedback").textContent="ყველა წყვილი ნაპოვნია! 🎉"}else{$("mFeedback").textContent="არ ემთხვევა, სცადე თავიდან";$("mFeedback").className="feedback bad"}selected=null;document.querySelectorAll("#kaTiles .tile").forEach(x=>x.classList.remove("selected"))})})}
function tile(parent,label,i,fn){let b=document.createElement("button");b.className="tile";b.textContent=label;b.dataset.i=i;b.onclick=fn;parent.appendChild(b)}
function builderNew(){current=nextWord();builderLetters=shuffle([...current.ru]);builderAnswer=[];$("bWord").textContent=current.ka;$("bFeedback").textContent="";builderDraw()}
function builderDraw(){$("bAnswer").innerHTML="";builderAnswer.forEach((c,i)=>{let x=document.createElement("span");x.className="slot";x.textContent=c;$("bAnswer").appendChild(x)});$("bLetters").innerHTML="";builderLetters.forEach((c,i)=>{let b=document.createElement("button");b.className="letter";b.textContent=c;b.disabled=builderAnswer.includes(i);if(b.disabled)b.classList.add("used");b.onclick=()=>{builderAnswer.push(i);builderDraw()};$("bLetters").appendChild(b)});$("bAnswer").innerHTML="";builderAnswer.forEach(i=>{let x=document.createElement("span");x.className="slot";x.textContent=builderLetters[i];$("bAnswer").appendChild(x)})}
$("bClear").onclick=()=>{builderAnswer=[];builderDraw()};$("bCheck").onclick=()=>{let val=builderAnswer.map(i=>builderLetters[i]).join("");if(val.toLocaleLowerCase("ru")===current.ru.toLocaleLowerCase("ru")){$("bFeedback").textContent="+15 🪙 იდეალურია!";$("bFeedback").className="feedback good";award(15)}else{$("bFeedback").textContent="ჯერ არ ემთხვევა. გადაალაგე ასოები.";$("bFeedback").className="feedback bad"}};
const scenes=["კაფეში ხარ. მიმტანი გეკითხება, რა გინდა.","მაღაზიაში გინდა ნივთის ყიდვა.","გზა აგერია და დახმარებას ითხოვ.","ახალ ნაცნობს ესალმები."];
function dialogueNew(){current=nextWord();$("dScene").textContent=scenes[Math.floor(Math.random()*scenes.length)];$("dWord").textContent=current.ka;$("dFeedback").textContent="აირჩიე სიტყვის რუსული ვარიანტი";$("dFeedback").className="feedback";$("dOptions").innerHTML="";shuffle([current.ru,...shuffle(words.filter(w=>w.ru!==current.ru)).slice(0,3).map(w=>w.ru)]).forEach(v=>{let b=document.createElement("button");b.className="option";b.textContent=v;b.onclick=()=>{[...$("dOptions").children].forEach(x=>x.disabled=true);if(v===current.ru){b.classList.add("correct");$("dFeedback").textContent="+12 🪙 სწორია!";$("dFeedback").className="feedback good";award(12)}else{$("dFeedback").textContent="სწორი პასუხია: "+current.ru;$("dFeedback").className="feedback bad"}$("dNext").disabled=false};$("dOptions").appendChild(b)});$("dNext").disabled=true}
function memoryNew(){let items=shuffle(Array.from({length:6},()=>nextWord()));memoryPairs=new Set();memoryPick=[];let cards=shuffle(items.flatMap((w,i)=>[{id:i,side:"ka",v:w.ka},{id:i,side:"ru",v:w.ru}]));$("memGrid").innerHTML="";$("memFeedback").textContent="";cards.forEach(c=>{let b=document.createElement("button");b.className="memcard";b.textContent="？";b.dataset.id=c.id;b.dataset.side=c.side;b.dataset.v=c.v;b.onclick=()=>{if(b.classList.contains("paired")||b.classList.contains("open")||memoryPick.length===2)return;b.classList.add("open");b.textContent=c.v;memoryPick.push(b);if(memoryPick.length===2){let [a,z]=memoryPick;if(a.dataset.id===z.dataset.id&&a.dataset.side!==z.dataset.side){a.classList.add("paired");z.classList.add("paired");memoryPairs.add(c.id);$("memFeedback").textContent="+8 🪙 წყვილი ნაპოვნია";$("memFeedback").className="feedback good";award(8);memoryPick=[];if(memoryPairs.size===6)$("memFeedback").textContent="დაფა დასრულებულია! 🎉"}else{setTimeout(()=>{memoryPick.forEach(x=>{x.classList.remove("open");x.textContent="？"});memoryPick=[]},700)}}};$("memGrid").appendChild(b)})}
function huntNew(){current=nextWord();huntTarget=current.ru.toLocaleLowerCase("ru").replace(/ё/g,"е");if(huntTarget.length>8){huntTarget=huntTarget.slice(0,8)}let chars=shuffle([...huntTarget]);let filler="абвгдежзийклмнопрстуфхцчшщыэюя";while(chars.length<64)chars.push(filler[Math.floor(Math.random()*filler.length)]);let cells=shuffle(chars);let start=Math.floor(Math.random()*(8-huntTarget.length+1))*8; // replace one horizontal segment with target
for(let i=0;i<huntTarget.length;i++)cells[start+i]=huntTarget[i];$("hWord").textContent=current.ka;$("hFeedback").textContent="";$("hFeedback").className="feedback";$("hGrid").innerHTML="";let chosen=[];cells.forEach((c,i)=>{let b=document.createElement("button");b.className="cell";b.textContent=c;b.onclick=()=>{if(b.classList.contains("mark"))return;let expected=huntTarget[chosen.length];if(c===expected){chosen.push(i);b.classList.add("mark");if(chosen.length===huntTarget.length){$("hFeedback").textContent="+15 🪙 ნაპოვნია!";$("hFeedback").className="feedback good";award(15)}}else{$("hFeedback").textContent="სხვა ასოა — დაიწყე სიტყვის პირველი ასოდან";$("hFeedback").className="feedback bad";chosen.forEach(j=>$("hGrid").children[j].classList.remove("mark"));chosen=[]}};$("hGrid").appendChild(b)})}
$("qNext").onclick=quizNew;$("mNext").onclick=matchNew;$("bNext").onclick=builderNew;$("dNext").onclick=dialogueNew;$("memNext").onclick=memoryNew;$("hNext").onclick=huntNew;$("homeBtn").onclick=()=>{$("gamePanel").hidden=true;window.scrollTo({top:0,behavior:"smooth"})};
$("addWord").onclick=()=>{let ka=$("newKa").value.trim(),ru=$("newRu").value.trim();if(!ka||!ru)return;if(words.some(w=>w.ka.toLowerCase()===ka.toLowerCase()&&w.ru.toLowerCase()===ru.toLowerCase()))return alert("ეს წყვილი უკვე არის.");words.push({ka,ru});$("newKa").value="";$("newRu").value="";freshDeck();save();renderCards();$("lexCount").textContent=`ლექსიკაში ${words.length} სიტყვაა`};
$("importFile").onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let t=await f.text(),arr=f.name.endsWith(".json")?JSON.parse(t):t.split(/\r?\n/).map(l=>{let a=l.split(/[,\t;]/);return{ka:a[0]?.trim(),ru:a.slice(1).join(",").trim()}});let n=0;arr.forEach(x=>{let ka=String(x.ka||x.georgian||"").trim(),ru=String(x.ru||x.russian||"").trim();if(ka&&ru&&!words.some(w=>w.ka===ka&&w.ru===ru)){words.push({ka,ru});n++}});freshDeck();save();renderCards();$("lexCount").textContent=`დაემატა ${n} სიტყვა`}catch(err){alert("ფაილის ფორმატი ვერ წავიკითხე.")}e.target.value=""};
$("exportBtn").onclick=()=>{let a=document.createElement("a"),u=URL.createObjectURL(new Blob([JSON.stringify(words,null,2)],{type:"application/json"}));a.href=u;a.download="ka-ru-words.json";a.click();URL.revokeObjectURL(u)};
$("resetBtn").onclick=()=>{if(confirm("განულდეს ქულები, გახსნილი თამაშები და დამატებული სიტყვები?")){localStorage.removeItem(STORE);location.reload()}};
$("welcomeClose").onclick=()=>$("welcome").style.display="none";
function init(){load();freshDeck();renderWallet();renderCards();renderShop();$("lexCount").textContent=`საწყისი ლექსიკა: ${words.length.toLocaleString('ka-GE')} სიტყვა-წყვილი`;let c=$("welcomeChoices");["quiz","match"].forEach(id=>{let m=modes.find(x=>x.id===id),b=document.createElement("button");b.className="btn secondary";b.innerHTML=m.emoji+" "+m.title;b.onclick=()=>{$("welcome").style.display="none";start(id)};c.appendChild(b)});$("welcome").style.display="flex"}window.addEventListener("app-auth-ready",init,{once:true});


