const $=id=>document.getElementById(id), key='ruska_study_v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){};saved.errors=saved.errors||{};saved.known=saved.known||{};saved.daily=saved.daily||{};
const put=()=>localStorage.setItem(key,JSON.stringify(saved)), today=new Date().toLocaleDateString('en-CA');
