const content=$('studyContent');function btn(label,fn,cls='btn'){let b=document.createElement('button');b.className=cls;b.textContent=label;b.onclick=fn;return b}function speak(t){if(!('speechSynthesis'in window)){alert('ამ ბრაუზერში გახმოვანება მიუწვდომელია.');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang='ru-RU';u.rate=.78;speechSynthesis.speak(u)}function panel(html){content.innerHTML=html}function render(tab){document.querySelectorAll('#studyTabs button').forEach(b=>{b.className='btn '+(b.dataset.tab===tab?'':'secondary')});
if(tab==='alphabet'){panel('<div class="studyCard"><b>რუსული ანბანი</b><p>დააჭირე ასოს, რომ მოისმინო მისი სახელი/ბგერა. ქართული მინიშნება მიახლოებითია.</p><div class="alphaGrid" id="alpha"></div><div id="alphaInfo" class="studyBig">აირჩიე ასო</div><div class="studyActions"><button class="btn secondary" id="sayAlpha">🔊 მოსმენა</button></div></div>');let g=$('alpha');alphabet.forEach(([a,h])=>{let d=document.createElement('button');d.className='alphaCell';d.innerHTML='<b>'+a+'</b><small>'+h+'</small>';d.onclick=()=>{$('alphaInfo').textContent=a+' — '+h;$('sayAlpha').onclick=()=>speak(a)};g.append(d)});}
if(tab==='path'){let steps=[['ანბანი და გამოთქმა','ასოების ამოცნობა და მარტივი წაკითხვა'],['პირველი სიტყვები','მისალმება, ოჯახი, საკვები და რიცხვები'],['მარტივი ფრაზები','მე მინდა…, მე ვიცი…, სად არის…'],['ზმნები და წინადადებები','ვინ რას აკეთებს და როდის'],['ყოველდღიური საუბარი','მაღაზია, კაფე, ტრანსპორტი'],['გრამატიკის საფუძვლები','სქესი, მრავლობითი, დროები'],['მოსმენა და საუბარი','მოკლე აუდიოები და დიალოგები']];let done=saved.steps||0;panel('<div class="studyCard"><b>შენი სასწავლო გზა</b><p>გაიარე ეტაპები თანმიმდევრობით. ეტაპის დასრულება შენს პროგრესს შეინახავს.</p><div class="studyProgress"><i style="width:'+Math.round(done/steps.length*100)+'%"></i></div><small>'+done+' / '+steps.length+' ეტაპი დასრულებულია</small></div>'+steps.map((x,i)=>'<div class="studyCard"><b>'+(i+1)+'. '+x[0]+'</b><p>'+x[1]+'</p><div class="studyActions">'+(i<done?'<span class="good">✓ დასრულებულია</span>':i===done?'<button class="btn" data-step="'+i+'">გაკვეთილის დაწყება</button>':'<span class="muted">ჯერ ჩაკეტილია</span>')+'</div></div>').join(''));content.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>lesson(+b.dataset.step));}
if(tab==='review'){let pool=words.filter(w=>saved.errors[w.ka]||!saved.known[w.ka]);let w=pool[Math.floor(Math.random()*pool.length)]||words[Math.floor(Math.random()*words.length)];panel('<div class="studyCard"><div class="hint">გაიხსენე რუსული თარგმანი</div><div class="studyBig">'+(w?.ka||'ლექსიკა ცარიელია')+'</div><div id="revAnswer" class="hint">პასუხი ჯერ დამალულია</div><div class="studyActions" id="revBtns"></div></div><p class="muted">გამეორებაში უპირატესობა ენიჭება რთულ და ჯერ უცნობ სიტყვებს.</p>');$('revBtns').append(btn('👁️ პასუხის ნახვა',()=>{$('revAnswer').textContent=w.ru;$('revBtns').innerHTML='';$('revBtns').append(btn('🔊 მოსმენა',()=>speak(w.ru),'btn secondary'),btn('ვიცოდი ✓',()=>{saved.known[w.ka]=true;delete saved.errors[w.ka];put();render('review')},'btn'),btn('გამიჭირდა ↻',()=>{saved.errors[w.ka]=(saved.errors[w.ka]||0)+1;put();render('review')},'btn secondary'))}));}
if(tab==='mistakes'){let list=Object.entries(saved.errors).sort((a,b)=>b[1]-a[1]);panel('<div class="studyCard"><b>ჩემი შეცდომების რვეული</b><p>აქ გროვდება სიტყვები, რომლებზეც გამეორებისას გაგიჭირდა.</p></div>'+(list.length?list.map(([ka,n])=>{let w=words.find(x=>x.ka===ka);return '<div class="shoprow"><div><b>'+ka+'</b><div class="small">'+(w?.ru||'')+' · შეცდომა: '+n+'</div></div><button class="btn secondary" data-clear="'+encodeURIComponent(ka)+'">გასუფთავება</button></div>'}).join(''):'<div class="studyCard good">ჯერ შეცდომები არ გაქვს — ითამაშე და აქ გამოჩნდება რთული სიტყვები.</div>'));content.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{delete saved.errors[decodeURIComponent(b.dataset.clear)];put();render('mistakes')});}
if(tab==='grammar'){let gs=[['არსებითი სახელის სქესი','რუსულში სიტყვა შეიძლება იყოს მამრობითი, მდედრობითი ან საშუალო სქესის. напр.: стол (მამრ.), книга (მდედრ.), окно (საშ.).','ხშირად დაბოლოება გეხმარება, მაგრამ გამონაკლისებიც არსებობს.'],['მხოლობითი და მრავლობითი','стол — столы; книга — книги.','ფორმა შეიძლება იცვლებოდეს სიტყვის მიხედვით.'],['პირის ნაცვალსახელები','я — მე; ты — შენ; он/она — ის; мы — ჩვენ; вы — თქვენ; они — ისინი.','ზმნის ფორმა ხშირად იცვლება იმის მიხედვით, ვინ მოქმედებს.'],['აწმყო და წარსული','я читаю — მე ვკითხულობ; я читал / читала — მე ვკითხულობდი.','წარსულ დროში ზმნა შეიძლება სქესის მიხედვითაც იცვლებოდეს.'],['მარტივი წინადადება','Я хочу воду. — მე წყალი მინდა. Я дома. — მე სახლში ვარ.','ჯერ ისწავლე მოკლე, პრაქტიკული წინადადებები.']];panel('<h3>გრამატიკა პატარა ნაბიჯებით</h3>'+gs.map((g,i)=>'<details class="studyCard"><summary><b>'+(i+1)+'. '+g[0]+'</b></summary><p style="margin-top:10px">'+g[1]+'</p><p class="small" style="margin-top:7px">'+g[2]+'</p></details>').join(''));}
if(tab==='listen'){let w=words[Math.floor(Math.random()*words.length)];panel('<div class="studyCard"><div class="hint">მოუსმინე რუსულ სიტყვას და აირჩიე ქართული მნიშვნელობა</div><div class="studyActions"><button class="btn" id="listenPlay">🔊 მოსმენა</button></div><div id="listenOpts" style="margin-top:12px"></div><div class="feedback" id="listenFeedback"></div><div class="studyActions"><button class="btn secondary" id="listenNext">შემდეგი სიტყვა →</button></div></div>');$('listenPlay').onclick=()=>speak(w.ru);let opts=[w,...shuffle(words.filter(x=>x.ka!==w.ka)).slice(0,3)];shuffle(opts).forEach(x=>{$('listenOpts').append(btn(x.ka,()=>{if($('listenFeedback').textContent)return;if(x.ka===w.ka){$('listenFeedback').textContent='სწორია! '+w.ru;$('listenFeedback').className='feedback good';award(5)}else{$('listenFeedback').textContent='სწორი პასუხია: '+w.ka+' — '+w.ru;$('listenFeedback').className='feedback bad';saved.errors[w.ka]=(saved.errors[w.ka]||0)+1;put()}},'studyChoice'))});$('listenNext').onclick=()=>render('listen');}if(tab==='speak'){let w=words[Math.floor(Math.random()*words.length)];panel('<div class="studyCard"><div class="hint">მოისმინე და გაიმეორე ხმამაღლა</div><div class="studyBig">'+w.ru+'</div><div class="hint">'+w.ka+'</div><div class="studyActions"><button class="btn" id="speakPlay">🔊 მოისმინე</button><button class="btn secondary" id="speakAgain">🔁 კიდევ ერთხელ</button><button class="btn secondary" id="speakKnown">გავიმეორე ✓</button></div><p class="small" style="text-align:center;margin-top:10px">გამოთქმის ავტომატური შეფასება ამ ვერსიაში არ არის — შეადარე შენი წარმოთქმა აუდიოს.</p></div>');$('speakPlay').onclick=()=>speak(w.ru);$('speakAgain').onclick=()=>speak(w.ru);$('speakKnown').onclick=()=>render('speak');} if(tab==='daily'){let d=saved.daily[today]||{new:0,review:0,dialogue:false};panel('<div class="studyCard"><b>დღევანდელი მიზანი</b><p>მოკლე, რეგულარული ვარჯიში — შენს ტემპში.</p><div class="studyProgress"><i style="width:'+Math.min(100,(d.new+d.review+(d.dialogue?1:0))/3*100)+'%"></i></div><p>ახალი სიტყვები: '+d.new+'/5 · გამეორება: '+d.review+'/5 · დიალოგი: '+(d.dialogue?'✓':'—')+'</p></div><div class="studyActions" id="dailyBtns"></div><p class="small" style="margin-top:10px">გეგმის შესრულება ინახება ამ მოწყობილობაზე.</p>');$('dailyBtns').append(btn('➕ ვისწავლე 5 ახალი სიტყვა',()=>{d.new=Math.min(5,d.new+5);saved.daily[today]=d;put();render('daily')}),btn('🧠 გავიმეორე 5 სიტყვა',()=>{d.review=Math.min(5,d.review+5);saved.daily[today]=d;put();render('daily')},'btn secondary'),btn('💬 შევასრულე დიალოგი',()=>{d.dialogue=true;saved.daily[today]=d;put();render('daily')},'btn secondary'));}}
function lesson(i){if(i===0){render('alphabet');return}let bank=words.slice(0,Math.min(words.length,[0,30,70,120,180,240,300][i]||words.length));let w=bank[Math.floor(Math.random()*bank.length)]||words[0];panel('<div class="studyCard"><div class="tag">ეტაპი '+(i+1)+'</div><h3>'+['','პირველი სიტყვები','მარტივი ფრაზები','ზმნები და წინადადებები','ყოველდღიური საუბარი','გრამატიკის საფუძვლები','მოსმენა და საუბარი'][i]+'</h3><div class="hint">ისწავლე ეს სიტყვა</div><div class="studyBig">'+w.ka+'</div><div class="hint">'+w.ru+'</div><div class="studyActions"><button class="btn secondary" id="lessonSound">🔊 მოსმენა</button><button class="btn" id="lessonNext">შემდეგი სიტყვა</button><button class="btn secondary" id="lessonDone">ეტაპის დასრულება ✓</button></div></div>');$('lessonSound').onclick=()=>speak(w.ru);$('lessonNext').onclick=()=>lesson(i);$('lessonDone').onclick=()=>{saved.steps=Math.max(saved.steps||0,i+1);put();render('path')};}
document.querySelectorAll('#studyTabs button').forEach(b=>b.onclick=()=>render(b.dataset.tab));render('path');
